/* Thu gọn (mặc định hub từ 23/10): nội dung lùi đúng bề rộng rail 58px — theme để 55px nên rail đè mép
   trái nội dung 3px. Rê chuột rail bung 220px đè lên, nội dung không xê dịch (SaleHubSidebar.vue). */
@media (min-width: 992px) {
body[data-sidebar-size='condensed'] .sale-theme .content-page {
    margin-left: 58px !important;
}
}
/* --- #1 Box tên phân hệ sát đỉnh + nổi bật --- */
.sale-theme .sale-cats .logo-box {
  margin-top: -60px;
  height: 60px;
  position: relative;
  background: linear-gradient(180deg, rgba(111, 178, 255, 0.22) 0%, rgba(53, 210, 223, 0.1) 55%, rgba(255, 255, 255, 0) 100%) !important;
  border-bottom: 1px solid rgba(111, 178, 255, 0.3) !important;
  box-shadow: 0 6px 16px rgba(10, 28, 61, 0.3);
}
.sale-theme .sale-cats .logo-box::after {
  content: "";
  position: absolute;
  left: 14px;
  right: 14px;
  bottom: -1px;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--sale-sky), transparent);
  opacity: .6;
}
.sale-theme .sale-cats .subsystem-name {
  color: #fff;
  font-weight: 800;
  letter-spacing: .6px;
  text-shadow: 0 1px 8px rgba(111, 178, 255, 0.35);
}
/* --- #2 Icon phân hệ ấn tượng --- */
.sale-theme .sale-cats .cats-brand-ic {
  width: 27px;
  height: 27px;
  filter: brightness(0) invert(1) drop-shadow(0 1px 5px rgba(111, 178, 255, 0.85));
}
/* --- Màu icon menu theo mockup (mỗi mục 1 màu qua --ic) --- */
.sale-theme .sale-cats .cat .cat-ic {
  color: var(--sale-on-navy-mut);
  color: var(--ic, var(--sale-on-navy-mut));
}
.sale-theme .sale-cats .cats-search {
  background: rgba(255, 255, 255, 0.08);
  border-color: rgba(255, 255, 255, 0.16);
  color: var(--sale-on-navy-mut);
}
.sale-theme .sale-cats .cats-search input {
    color: #fff;
}
.sale-theme .sale-cats .cat.on {
  background: rgba(111, 178, 255, 0.16) !important;
  color: #eaf7ff !important;
  border-left-color: var(--sale-sky) !important;
  box-shadow: inset 0 0 0 1px rgba(111, 178, 255, 0.18);
}
.sale-theme .sale-cats .cat.on .cat-ic, .sale-theme .sale-cats .cat.on .cat-arrow {
  color: var(--sale-sky) !important;
}
.sale-theme .sale-cats .cat:hover {
  background: rgba(255, 255, 255, 0.07);
}
/* ============ 2) TOPBAR (navy gradient + ánh sáng + wave line mép dưới) ============ */
.sale-theme .navbar-custom {
