.ff .ff__control div.v2-datepicker__wrapper div.v2-datepicker.v2-datepicker--sm .mx-input-wrapper input.mx-input,
.ff .ff__control div.v2-datepicker.v2-datepicker--sm .mx-input-wrapper input.mx-input,
.ff .ff__control div.v2-datepicker.v2-datepicker--sm .mx-input,
.ff .ff__control .mx-input {
  height: var(--ff-h) !important;
  min-height: var(--ff-h) !important;
  max-height: var(--ff-h) !important;
