.ff:not(.is-float) .ff__control .select2-selection--single .select2-selection__rendered .select2-selection__placeholder,
.ff:not(.is-float) .ff__control .select2-selection__placeholder {
  color: transparent !important;
}
.ff__label {
  position: absolute;
  top: 50%;
  left: calc(var(--ff-pad-x) - 4px);
  z-index: 2;
  display: flex;
  align-items: center;
  grid-gap: 4px;
  gap: 4px;
  max-width: calc(84% - 26px);
  padding: 0 4px;
  font-size: 11px;
  line-height: 1;
  color: var(--ff-muted);
  white-space: nowrap;
  background: var(--ff-notch-bg);
  pointer-events: none;
  transform: translateY(-50%) scale(var(--ff-grow));
