/* ── Khuôn hiển thị file, đồng bộ với màn Meeting (tab Biên bản) ───────────────── */
.v2-file__uploading {
  display: inline-flex;
  align-items: center;
  font-size: 12px;
  color: #64748b;
}
.v2-file__row {
  display: flex;
  align-items: center;
  grid-gap: 4px;
  gap: 4px;
  min-width: 0;
}
.v2-file__type-icon {
  font-size: 16px;
