  overflow: hidden;
}
.v2-file:hover {
    border-color: #16a34a;
    background-color: rgba(22, 163, 74, 0.02);
}
.v2-file[focus-within] {
    border-color: #16a34a;
    box-shadow: 0 0 0 2px rgba(22, 163, 74, 0.15);
}
.v2-file:focus-within {
    border-color: #16a34a;
    box-shadow: 0 0 0 2px rgba(22, 163, 74, 0.15);
}
.v2-file--disabled, .v2-file[disabled] {
    cursor: not-allowed;
    background-color: #f1f5f9;
    opacity: 0.6;
    pointer-events: none;
}
.v2-file__input {
  position: absolute;
  width: 100%;
  height: 100%;
  opacity: 0;
  cursor: pointer;
  z-index: 1;
}
.v2-file__label {
  display: flex;
  align-items: center;
  grid-gap: 8px;
  gap: 8px;
  width: 100%;
  padding: 8px 10px;
  pointer-events: none;
}
.v2-file__icon {
  flex-shrink: 0;
  color: #64748b;
}
.v2-file__text {
  flex: 1;
  font-size: 13px;
  color: #0f172a;
  text-align: left;
}
.v2-file--xs .v2-file__label {
  padding: 6px 8px;
}
.v2-file--xs .v2-file__text {
  font-size: 12px;
}
.v2-file--xs .v2-file__icon {
  width: 14px;
  height: 14px;
}
.v2-file--sm .v2-file__label {
  padding: 6px 10px;
}
.v2-file--sm .v2-file__text {
  font-size: 12px;
}
.v2-file--sm .v2-file__icon {
  width: 16px;
  height: 16px;
}
.v2-file--md .v2-file__label {
  padding: 8px 10px;
}
.v2-file--md .v2-file__text {
  font-size: 13px;
}
.v2-file--md .v2-file__icon {
  width: 16px;
  height: 16px;
}
.v2-file--lg .v2-file__label {
  padding: 10px 12px;
}
.v2-file--lg .v2-file__text {
  font-size: 14px;
}
.v2-file--lg .v2-file__icon {
  width: 18px;
  height: 18px;
}
.v2-file__preview {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 6px;
  padding: 6px 10px;
  background-color: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 5px;
  font-size: 12px;
  color: #0f172a;
}
.v2-file__preview-text {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.v2-file__remove {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  margin-left: 8px;
  padding: 0;
  border: none;
  background: transparent;
  color: #64748b;
  cursor: pointer;
  border-radius: 3px;
  transition: background-color 0.15s, color 0.15s;
}
.v2-file__remove:hover {
    background-color: #e2e8f0;
    color: #0f172a;
}
.v2-file__remove svg {
    width: 14px;
    height: 14px;
}
.v2-file__files-list {
  margin-top: 8px;
  border: 1px solid #e2e8f0;
  border-radius: 5px;
  background-color: #f8fafc;
  overflow: hidden;
}
.v2-file__files-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 10px;
  background-color: #f1f5f9;
  border-bottom: 1px solid #e2e8f0;
}
.v2-file__files-count {
  font-size: 12px;
  font-weight: 600;
  color: #0f172a;
}
.v2-file__remove-all {
  font-size: 11px;
  color: #dc2626;
  background: transparent;
