}
.v2-file__files-items {
  max-height: 200px;
  overflow-y: auto;
}
.v2-file__file-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 10px;
  border-bottom: 1px solid #f1f5f9;
}
.v2-file__file-item:last-child {
    border-bottom: none;
}
.v2-file__file-item:hover {
    background-color: #f1f5f9;
}
.v2-file__file-name {
  flex: 1;
  font-size: 12px;
  color: #374151;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  margin-right: 8px;
}
.v2-file__remove-file {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 16px;
  height: 16px;
  padding: 0;
  border: none;
  background: transparent;
  color: #9ca3af;
  cursor: pointer;
  border-radius: 2px;
  transition: background-color 0.15s, color 0.15s;
}
.v2-file__remove-file:hover {
    background-color: #e5e7eb;
    color: #6b7280;
}
.v2-file__remove-file svg {
    width: 10px;
    height: 10px;
}

