.mk-filter-pop[data-cols="3"] .form-row>div:has(> .ff--range){flex:0 0 66.666%;max-width:66.666%}
.mk-filter-pop[data-cols="4"] .form-row>div:has(> .ff--range){flex:0 0 50%;max-width:50%}

/* Tiêu đề dòng Nhiệm vụ/Vấn đề + tiêu đề nhóm: 13px, đồng nhất với tiêu đề cùng cấp ở các màn khác */
.mk-lr-title{font-size:13px}
.mk-lg-h b{font-size:13px}
/* Nút đóng/mở tất cả nhóm (chỉ hiện ở cách xem Danh sách — nằm trong .mk-gb) */
.mk-fa-btn{width:32px;padding:0;justify-content:center}
.mk-fa-btn:hover{border-color:#1abc9c}.mk-fa-btn:hover i{color:#0f766e}
.mk-fa-btn:disabled{opacity:.5;cursor:default}

/* Màn hẹp (< 1500px): thanh công cụ không tràn — ô tìm co lại, Sắp xếp + Danh sách/Bảng chỉ còn icon (giữ title) */
@media (max-width:1499px){
.mk-tb .quick-search{flex:0 1 300px;min-width:180px}
.mk-srt-btn>span{display:none}
.mk-vt button{font-size:0;gap:0;padding:0 8px}
.mk-vt button i{font-size:15px}
}
.mk-tb-chips .due-pill{white-space:nowrap}
.mk-tb .v2-btn{white-space:nowrap;flex-shrink:0}

/* ===== 04/11: màn Tổng quan — header card theo CHUẨN HEADER KHỐI CHUNG của phần mềm
   (hrm-client assets/scss/default.scss `body .card .card-header.section-header`, chốt 19/10/2026):
   dải nền slate .07 · cao tối thiểu 36px · đệm 2px 10px · tiêu đề 14px đậm #1f2937 căn giữa dọc · không kẻ dưới ===== */
.categories-table-wrap .table-header,.approval-card .approval-header{min-height:36px;padding:2px 10px!important;background:rgba(100,116,139,.07)!important;border-bottom:0!important;display:flex;align-items:center}
.table-header .table-title,.approval-header .approval-title,.chart-hd .chart-title{font-size:14px!important;font-weight:700!important;line-height:20px!important;color:#1f2937!important;margin:0!important}
.chart-box > .chart-hd{margin:-12px -12px 10px!important;min-height:36px;padding:2px 10px;background:rgba(100,116,139,.07);border-radius:15px 15px 0 0;align-items:center}

/* 04/11: nhóm “Hôm nay” trống (gom theo Hạn) */
.mk-lv .mk-lg-empty{display:flex;align-items:center;gap:6px;padding:10px 16px 12px 40px;font-size:12.5px;color:#94a3b8}
.mk-lv .mk-lg-empty i{font-size:15px;color:#cbd5e1}
/* 05/11 — U31b công tắc duyệt triển khai · U36 báo trước trạng thái vấn đề */
.mk-td-tog{display:flex;flex-direction:column;gap:4px;background:#f8fafc;border:1px solid #edf1f5;border-radius:8px;padding:8px 10px;margin-bottom:12px}
.mk-td-tog label{display:flex;align-items:center;gap:8px;margin:0;font-size:13px;color:#1f2937;cursor:pointer}
.mk-td-tog label b{font-weight:600}.mk-td-tog small{font-size:12px;color:#6b7280;padding-left:22px}
.mk-td-tog .mk-td-now{padding-left:22px;font-size:12.5px;color:#374151}.mk-td-tog .mk-td-now[hidden]{display:none}
.mk-td-route{display:flex;align-items:flex-start;gap:6px;font-size:12.5px;color:#374151;background:#f0f9ff;border:1px solid #bae6fd;border-radius:8px;padding:8px 10px;margin:-2px 0 12px}
.mk-td-route i{color:#0ea5e9;margin-top:1px}.mk-td-route:empty{display:none}
.mk-tdm-row>.mk-tdm-f.c4{grid-column:span 4}.mk-tdm-row>.mk-tdm-f.c6{grid-column:span 6}.mk-tdm-row>.mk-tdm-f.c12{grid-column:span 12}
/* 05/11 — form Tạo/Sửa theo khuôn app: chip ưu tiên tô màu, hàng + Thêm, Thiết lập trong form */
.mk-td-prio{display:flex;gap:6px;flex-wrap:wrap}
.mk-td-prio button{display:inline-flex;align-items:center;gap:4px;height:32px;padding:0 14px;border-radius:6px;border:1px solid color-mix(in srgb,var(--pc) 40%,#fff);background:color-mix(in srgb,var(--pc) 10%,#fff);color:var(--pc);font-size:13px;font-weight:600;cursor:pointer}
.mk-td-prio button.on{background:var(--pc);border-color:var(--pc);color:#fff}
.mk-td-addrow{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:2px 0 12px}.mk-td-addrow>span{font-size:12px;color:#6b7280}
.mk-td-addrow .mk-td-add[hidden],.mk-td-fsec[hidden]{display:none}
.mk-td-fset{border:1px solid #edf1f5;border-radius:8px;margin-bottom:12px;background:#fff}
.mk-td-fset h6{display:flex;align-items:center;gap:8px;margin:0;padding:10px 12px;font-size:13.5px;font-weight:600;color:#1f2937;cursor:pointer}
.mk-td-fset h6 em{font-style:normal;font-size:11.5px;font-weight:600;color:#475569;background:#f1f5f9;border-radius:10px;padding:1px 8px}
.mk-td-fset h6 small{flex:1;min-width:0;font-size:12px;font-weight:400;color:#6b7280;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mk-td-fset .mk-td-car{transition:transform .15s}.mk-td-fset.open .mk-td-car{transform:rotate(180deg)}
.mk-td-fsetb{display:none;padding:4px 12px 12px;border-top:1px solid #edf1f5}.mk-td-fset.open .mk-td-fsetb{display:block}
.mk-td-form .mk-tdm-f small.mk-td-mut,.mk-td-setd{display:block;font-size:11.5px;color:#6b7280;margin-top:2px}.mk-td-setd{margin:-6px 0 10px}
.mk-td-chips-f small.mk-td-mut{margin-left:4px;font-size:11.5px;color:#94a3b8}
.mk-td-addrow:not(:has(.mk-td-add:not([hidden]))){display:none}
.mk-td-fsetb .mk-tdm-f,.mk-td-fsetb .mk-tdm-row{margin-bottom:10px}
/* 05/11 — Checklist + Nhiệm vụ con trong form (bám CreateTaskModal.vue) */
.mk-fblk{border:1px solid #edf1f5;border-radius:8px;padding:10px 12px;margin-bottom:12px;background:#fff}
.mk-fblk-h{display:flex;align-items:center;gap:8px;margin-bottom:8px}
.mk-fblk-ic{width:24px;height:24px;border-radius:6px;background:#e8f8f5;color:#1abc9c;display:inline-flex;align-items:center;justify-content:center;font-size:14px}
.mk-fblk-h b{font-size:13.5px;font-weight:600;color:#1f2937}.mk-fblk-n{font-size:12px;color:#6b7280;margin-left:auto}
.mk-fquick{display:inline-flex;align-items:center;gap:4px;height:26px;padding:0 10px;border-radius:6px;border:1px dashed #94d8c9;background:#f0fbf8;color:#0f8a72;font-size:12px;font-weight:600;cursor:pointer}
.mk-fadd{display:flex;gap:6px;margin-bottom:8px}.mk-fadd input{flex:1}
.mk-fic{flex:0 0 32px;width:32px;height:31px;border-radius:6px;border:1px solid transparent;background:transparent;color:#64748b;display:inline-flex;align-items:center;justify-content:center;cursor:pointer}
.mk-fic.bd{border-color:#d1d5db;background:#fff}.mk-fic:hover{background:#f1f5f9;color:#1f2937}.mk-fic[data-cldel]:hover,.mk-fic[data-subdel]:hover{color:#dc2626}
.mk-fcl-list{display:flex;flex-direction:column;gap:6px;max-height:220px;overflow:auto}
.mk-fcl-i{display:flex;align-items:center;gap:6px}.mk-fcl-i input[type=checkbox]{width:16px;height:16px;accent-color:#1abc9c;flex:0 0 16px}
.mk-fcl-i .form-control{flex:1}.mk-fcl-i .strike{text-decoration:line-through;color:#94a3b8}
.mk-fdrag{color:#cbd5e1;cursor:grab;font-size:15px}
.mk-fsub-hd,.mk-fsub-i{display:grid;grid-template-columns:22px 1fr 150px 128px 84px 32px;gap:6px;align-items:center}
.mk-fsub-hd{font-size:11.5px;font-weight:600;color:#6b7280;margin-bottom:4px}
.mk-fsub-i{margin-bottom:6px}.mk-fsub-i.add{padding-bottom:8px;border-bottom:1px dashed #e5e7eb;margin-bottom:8px}
.mk-fsub-list .mk-fsub-i{background:#fafbfc;border:1px solid #edf1f5;border-radius:6px;padding:6px}
.mk-fsub-n{color:#94a3b8;text-align:center;font-size:14px}
.mk-fsub-err{grid-column:2/-1;color:#dc2626;font-size:11.5px}.mk-fsub-err:empty{display:none}
.mk-fsub-list{max-height:260px;overflow:auto}
.mk-fsub-list .mk-fsub-i{background:none;border:0;border-radius:0;padding:0}
/* 05/11 [U] Ngày bắt đầu tuỳ chọn */
.mk-td-addstart{display:inline-flex;align-items:center;gap:3px;height:26px;padding:0 10px;margin-left:6px;border-radius:13px;border:1px dashed #94d8c9;background:#f0fbf8;color:#0f8a72;font-size:12px;font-weight:600;cursor:pointer}
.mk-td-addstart[hidden],.mk-td-startrow[hidden]{display:none}.mk-td-startrow{margin-top:-2px}
.mk-td-starthint{justify-content:flex-end;padding-bottom:4px}
